<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Controlled IDOR Lab</title><style>body{font:16px system-ui;max-width:900px;margin:40px auto;padding:0 20px;background:#101418;color:#edf2f7}a{color:#67e8a5}input,select{padding:9px}.card{border:1px solid #34404a;padding:18px;margin-top:20px}.warning{color:#fbbf24}</style></head><body><a href="<?= e(url('/lab')) ?>">&larr; Lab registry</a><h1>Synthetic Object Authorization</h1><p class="warning">CONTROLLED LAB &middot; <?= e($module['state']) ?> &middot; no real document IDs</p><form method="get"><label>Lab identity<select name="actor"><option <?= $actor==='analyst-a'?'selected':'' ?>>analyst-a</option><option <?= $actor==='analyst-b'?'selected':'' ?>>analyst-b</option></select></label><label>Object ID<input name="id" value="<?= e($objectId) ?>" placeholder="LAB-1001"></label><button type="submit">Retrieve</button></form><?php if($objectId!==''): ?><?php if($object): ?><div class="card"><strong><?= e($object['id'].' — '.$object['title']) ?></strong><p>Owner: <?= e($object['owner']) ?></p><p><?= e($object['classification']) ?></p></div><?php else: ?><p class="card">Object not found or not authorized.</p><?php endif; ?><?php endif; ?></body></html>
